const MISSIONS=[
{key:"likely",kind:"screen",when:"Icebreaker — play first",title:"Most Likely To",rules:"A prompt appears. Chalk the name of the person it fits best. Boards up together. Points for the person named — and a reputation.",hasShield:false,total:10},
{key:"quiz",kind:"screen",when:"Early",title:"Rapid Quiz",rules:"Question on screen. First to shout is locked in — right or wrong, that is their answer. Correct takes the point. Three parts: easy, then medium, then brutal.",hasShield:true,total:30},
{key:"countdown",kind:"screen",when:"Any time",title:"Longest Word",rules:"Twelve letters, and the clock starts with them. Longest real word on your chalkboard wins the round.",hasShield:true,total:10},
{key:"estimate",kind:"screen",when:"Any time",title:"Closest Guess",rules:"Write a number on your chalkboard. Closest to the truth wins each round.",hasShield:true,total:12},
{key:"memory",kind:"screen",when:"Any time",title:"Memory Wall",rules:"Twenty-five things appear, but not for long. Then chalk every one you remember.",hasShield:true,total:0},
{key:"snap",kind:"screen",when:"Any time",title:"Snap",rules:"A symbol changes every five seconds. When it matches the one before, shout SNAP. First correct scores. Wrong shout loses a point.",hasShield:true,total:0},
{key:"rps",kind:"physical",when:"Any time",title:"Rock Paper Scissors Royale",rules:"Everyone stands. Pair up, best of one, losers sit and cheer. Odd number: whoever is left without a partner gets a bye that round. Repeat until one stands.",hasShield:true,total:0},
{key:"oneleg",kind:"physical",when:"Any time",title:"One Leg",rules:"Stand on one leg, eyes closed, hands on head. Wobble and you are out. Last standing wins.",hasShield:true,total:0},
{key:"charades",kind:"screen",when:"Later — best with Ghosts",title:"Screen Charades",rules:"Everyone blindfolds on except the actor, who reads the screen. Blindfolds off, actor mimes against the clock. Guesser and actor both score.",hasShield:true,total:0},
{key:"hum",kind:"screen",when:"Later — best with Ghosts",title:"Hum It",rules:"Everyone blindfolds on except the hummer, who reads the song on screen. Blindfolds off, hum against the clock. Guesser and hummer both score.",hasShield:true,total:0},
{key:"statue",kind:"physical",when:"Late — needs Ghosts",title:"The Statue",rules:"Everyone stands and freezes. The Ghosts may do anything to make you laugh or move — except touch you. Last statue standing wins.",hasShield:true,total:0},
{key:"truths",kind:"screen",when:"Any time — nothing to prepare",title:"Two Truths and a Lie",rules:"One of you stands and tells us three things about yourself. Two are true, one is a lie. The table chalks 1, 2 or 3. Spot the lie and you score; fool the table and you score for everyone you fooled.",hasShield:true,total:5},
{key:"draw",kind:"screen",when:"Later — best with Ghosts",title:"Chalkboard Pictionary",rules:"Everyone blindfolds on except the artist, who reads the screen. Blindfolds off: they draw it on their chalkboard against the clock, no letters, no numbers. Guesser and artist both score.",hasShield:true,total:0},
{key:"hilo",kind:"screen",when:"Any time",title:"Higher or Lower",rules:"Everyone stands. A question, and a number: is the real answer higher or lower? On three, thumbs up for higher, down for lower. Wrong, and you sit. Last one standing wins the round.",hasShield:true,total:4},
{key:"change",kind:"screen",when:"Any time",title:"What Changed?",rules:"Twelve symbols appear. Study them. The screen goes dark for ten seconds — and something changes. When the grid comes back, first to shout what changed takes the point.",hasShield:true,total:6},
{key:"dilemma",kind:"screen",when:"When nobody holds a shield",addon:true,title:"The Dilemma",rules:"Chalk POT or SHIELD, board face down. Exactly one SHIELD: they take it and the pot grows by {P}. Two or more: nobody gets it and the pot loses {P}. Nobody: the pot grows by {P2}.",hasShield:true,total:0},
{key:"custom",kind:"physical",when:"Any time",title:"Custom Mission",rules:"Host explains the rules.",hasShield:true,total:0}];

const MODES={
  murder:{label:"Poison",desc:"Cloaks choose a Candle to poison. They find out at night, keep it to themselves, and announce it at dawn. A shield blocks it (nobody dies, TV says the shield held). The normal night."},
  convert:{label:"Conversion",desc:"No poison. Cloaks invite one Candle to join them. That person can accept (becomes a Cloak, meets the others) or refuse (stays a Candle; Cloaks know they refused). Candles only see ‘nobody died’. Use when Cloaks are down to one."},
  bargain:{label:"Bargain",desc:"Join or die. Cloaks pick a Candle: accept and they become a Cloak; refuse and they are poisoned on the spot (a shield still saves them). Harsher Conversion — use when Cloaks are down to one and the pool is big."}};
